using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using Autodesk.Revit.UI;
using Autodesk.Revit.DB;
using Panel = System.Windows.Controls.Panel;
using TextBox = System.Windows.Controls.TextBox;
using Grid = System.Windows.Controls.Grid;
using System.Windows.Controls.Primitives;
namespace BIMaestro.PropertiesTests {
public static class Experiment {
  static void Fingerprint(UIApplication app,string dir,StringBuilder report){if(app.ActiveUIDocument==null)return;var doc=app.ActiveUIDocument.Document;var elements=new List<Element>{app.ActiveUIDocument.ActiveView};elements.AddRange(new FilteredElementCollector(doc).OfClass(typeof(Wall)).Cast<Element>());var lines=new List<string>();foreach(var e in elements)foreach(Parameter p in e.Parameters){string value;try{switch(p.StorageType){case StorageType.String:value=p.AsString()??"<null>";break;case StorageType.Integer:value=p.AsInteger().ToString(CultureInfo.InvariantCulture);break;case StorageType.Double:value=p.AsDouble().ToString("R",CultureInfo.InvariantCulture);break;case StorageType.ElementId:value=p.AsElementId().ToString();break;default:value="<none>";break;}}catch(Exception ex){value="<error:"+ex.GetType().Name+">";}lines.Add(e.Id+"|"+p.Id+"|"+p.Definition.Name+"|"+p.StorageType+"|"+value);}lines.Sort(StringComparer.Ordinal);string data=string.Join("\n",lines);string hash;using(var sha=SHA256.Create())hash=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(data))).Replace("-","");report.AppendLine("Parameter fingerprint SHA256="+hash+" Entries="+lines.Count);File.WriteAllText(Path.Combine(dir,"parameter-fingerprint.txt"),hash+Environment.NewLine+data);}
 static ExternalEvent refreshEvent; static string contextLabel=""; static bool? forcedTheme; static System.Windows.Controls.Button searchButton;
 sealed class RefreshHandler:IExternalEventHandler {
  public string GetName(){return "Actualiser les repères de propriétés";}
  public void Execute(UIApplication app){if(popup!=null&&popup.IsOpen)Load(app);}
 }
 static Panel host; static FrameworkElement selector; static Border box; static TextBox search; static TextBlock results; static bool dark; static System.Windows.Interop.HwndSource source; static Popup popup; static readonly List<string> rows=new List<string>();
 static IEnumerable<DependencyObject> Walk(DependencyObject o,int d=0){if(o==null||d>60)yield break;yield return o;int n=0;try{n=VisualTreeHelper.GetChildrenCount(o);}catch{}for(int i=0;i<n;i++)foreach(var c in Walk(VisualTreeHelper.GetChild(o,i),d+1))yield return c;}
 static IEnumerable<DependencyObject> Roots(){foreach(PresentationSource p in PresentationSource.CurrentSources)if(p.RootVisual!=null)yield return p.RootVisual;}
 static SolidColorBrush B(string s){return new SolidColorBrush((System.Windows.Media.Color)ColorConverter.ConvertFromString(s));}
 static void Theme(){if(box==null)return;box.Background=B(dark?"#20312B":"#EDF5F0");box.BorderBrush=B("#28694B");results.Foreground=B(dark?"#ECF2EE":"#183E2C");search.Background=B(dark?"#15231D":"#FFFFFF");search.Foreground=B(dark?"#FFFFFF":"#183E2C");if(searchButton!=null){searchButton.Background=box.Background;searchButton.Foreground=results.Foreground;}}
 static void Update(){if(results==null)return;string q=search.Text.Trim();var matches=rows.Where(x=>CultureInfo.CurrentCulture.CompareInfo.IndexOf(x,q,CompareOptions.IgnoreCase|CompareOptions.IgnoreNonSpace)>=0).ToArray();results.Text=contextLabel+"\n"+(q.Length==0?rows.Count+" propriétés · saisissez un nom ou une valeur":matches.Length+" résultat(s) · lecture seule\n"+string.Join("\n",matches));}
 static void Load(UIApplication app){rows.Clear();if(app.ActiveUIDocument==null){contextLabel="Aucun document actif";Update();return;}var doc=app.ActiveUIDocument.Document;var ids=app.ActiveUIDocument.Selection.GetElementIds();if(ids.Count>1){contextLabel="Sélection multiple : choisissez un seul élément";Update();return;}Element e=ids.Count==1?doc.GetElement(ids.First()):app.ActiveUIDocument.ActiveView;contextLabel=(ids.Count==1?"Élément : ":"Vue : ")+(e?.Name??"Indisponible");if(e!=null)foreach(Parameter p in e.Parameters)try{rows.Add(p.Definition.Name+" : "+(p.AsValueString()??p.AsString()??"—"));}catch{}rows.Sort(StringComparer.CurrentCultureIgnoreCase);if(forcedTheme.HasValue)dark=forcedTheme.Value;else try{var property=typeof(UIApplication).Assembly.GetType("Autodesk.Revit.UI.UIThemeManager")?.GetProperty("CurrentTheme");dark=Convert.ToString(property?.GetValue(null,null))=="Dark";}catch{}Theme();Update();}
 public static void Run(UIApplication app,string dir){string cmd=File.ReadAllText(Path.Combine(dir,"experiment.txt")).Trim();var log=new StringBuilder();log.AppendLine("Command="+cmd);if(cmd=="restore"){if(refreshEvent!=null){refreshEvent.Dispose();refreshEvent=null;}forcedTheme=null;rows.Clear();if(popup!=null)popup.IsOpen=false;if(source!=null&&host!=null){host.Children.Remove(selector);source.RootVisual=selector;}host=null;box=null;search=null;results=null;popup=null;source=null;searchButton=null;selector=null;}else if(cmd=="inspect"){foreach(var s in Roots().SelectMany(x=>Walk(x)).Where(x=>x.GetType().FullName=="UIFramework.TypeSelectorToolBarControl"))for(DependencyObject p=s;p!=null;p=VisualTreeHelper.GetParent(p)){var f=p as FrameworkElement;log.AppendLine(p.GetType().FullName+" name="+f?.Name+" size="+f?.ActualWidth+"x"+f?.ActualHeight);}}else if(cmd=="add"){
 if(box==null){selector=Roots().SelectMany(x=>Walk(x)).OfType<FrameworkElement>().FirstOrDefault(x=>x.GetType().FullName=="UIFramework.TypeSelectorToolBarControl");if(selector==null)throw new Exception("Selector missing");source=PresentationSource.FromVisual(selector) as System.Windows.Interop.HwndSource;if(source==null||source.RootVisual!=selector)throw new Exception("Unexpected root; no mutation");search=new TextBox{Margin=new Thickness(5),Padding=new Thickness(4),ToolTip="Recherche dans la sélection — lecture seule"};search.TextChanged+=(o,e)=>Update();results=new TextBlock{Margin=new Thickness(6,0,6,6),TextWrapping=TextWrapping.Wrap,FontSize=11};var inner=new StackPanel();inner.Children.Add(search);inner.Children.Add(new ScrollViewer{MaxHeight=280,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Content=results});box=new Border{BorderThickness=new Thickness(1),Width=380,Child=inner};var button=new System.Windows.Controls.Button{Content="⌕",Width=22,Height=20,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Bottom,ToolTip="Repères : rechercher une propriété (lecture seule)"};popup=new Popup{Child=box,PlacementTarget=button,Placement=PlacementMode.Bottom,StaysOpen=false,AllowsTransparency=true};searchButton=button;refreshEvent=ExternalEvent.Create(new RefreshHandler());button.Click+=(o,e)=>{popup.IsOpen=!popup.IsOpen;if(popup.IsOpen){search.Focus();refreshEvent.Raise();}};host=new Grid();source.RootVisual=null;host.Children.Add(selector);host.Children.Add(button);source.RootVisual=host;Theme();}Load(app);popup.IsOpen=false;
 }else if(cmd=="show"||cmd=="hide"){popup.IsOpen=cmd=="show";}else if(cmd.StartsWith("query ")){Load(app);search.Text=cmd.Substring(6);}else if(cmd=="context")Load(app);else if(cmd=="dark"||cmd=="light"){forcedTheme=cmd=="dark";dark=forcedTheme.Value;Theme();}
 Fingerprint(app,dir,log);log.AppendLine("Extension="+(box!=null)+" Parent="+host?.GetType().FullName+" rows="+rows.Count+" dark="+dark+" results="+results?.Text);File.WriteAllText(Path.Combine(dir,"experiment-report.txt"),log.ToString());File.WriteAllText(Path.Combine(dir,"2026-"+cmd.Split(' ')[0]+"-report.txt"),log.ToString());}
}
}
